import React, { Component, Fragment } from "react";
import { MDBDataTable, MDBBtn } from "mdbreact";
import { Card, CardBody, CardHeader } from "reactstrap";

class Clients extends Component {
  render() {
    const data = {
      columns: [
        {
          label: "Id",
          field: "id",
          sort: "asc"
        },
        {
          label: "Name",
          field: "name",
          sort: "asc"
        },
        {
          label: "CreatedBy",
          field: "createdBy",
          sort: "asc"
        },
        {
          label: "Actions",
          field: "actions",
          sort: "asc"
        }
      ],
      rows: [
        {
          id: "Tiger Nixon",
          name: "System Architect",
          createdBy: "Edinburgh",
          action: "61",
          date: "2011/04/25",
          salary: "$320"
        },
        {
          id: "Garrett Winters",
          name: "Accountant",
          createdBy: "Tokyo",
          action: <h1>Tiger Nixon</h1>,
          date: "2011/07/25",
          salary: "$170"
        }
      ]
    };

    return (
      <Card>
        <CardHeader>
          <h4>Clients</h4>
        </CardHeader>
        <CardBody>
          <MDBDataTable striped bordered hover data={data} />
        </CardBody>
      </Card>
    );
  }
}
export default Clients;
